CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE workspaces (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE users (id uuid PRIMARY KEY, workspace_id uuid NOT NULL REFERENCES workspaces(id), email text NOT NULL, name text NOT NULL, role text NOT NULL CHECK (role IN ('employee','manager','finance','administrator')), UNIQUE (workspace_id, email));
CREATE TABLE expense_reports (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL REFERENCES workspaces(id), employee_id uuid NOT NULL REFERENCES users(id), title text NOT NULL, description text NOT NULL DEFAULT '', currency char(3) NOT NULL, total_amount numeric(14,2) NOT NULL DEFAULT 0, status text NOT NULL DEFAULT 'draft' CHECK (status IN ('draft','submitted','approved','rejected','paid')), submitted_at timestamptz, approved_at timestamptz, paid_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE expense_items (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), report_id uuid NOT NULL REFERENCES expense_reports(id) ON DELETE CASCADE, spent_on date NOT NULL, category text NOT NULL CHECK (category IN ('travel','meals','lodging','software','office','transport','other')), description text NOT NULL, amount numeric(14,2) NOT NULL CHECK (amount >= 0));
CREATE TABLE expense_approvals (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), report_id uuid NOT NULL REFERENCES expense_reports(id), manager_id uuid NOT NULL REFERENCES users(id), decision text NOT NULL CHECK (decision IN ('approved','rejected')), comment text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE expense_comments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), report_id uuid NOT NULL REFERENCES expense_reports(id) ON DELETE CASCADE, author_id uuid NOT NULL REFERENCES users(id), body text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE expense_attachments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), report_id uuid NOT NULL REFERENCES expense_reports(id) ON DELETE CASCADE, item_id uuid REFERENCES expense_items(id) ON DELETE CASCADE, object_key text NOT NULL UNIQUE, filename text NOT NULL, content_type text NOT NULL, size_bytes bigint NOT NULL, uploaded_by uuid NOT NULL REFERENCES users(id), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE expense_activities (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), report_id uuid NOT NULL REFERENCES expense_reports(id) ON DELETE CASCADE, actor_id uuid REFERENCES users(id), action text NOT NULL, metadata jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX expense_reports_queue_idx ON expense_reports (workspace_id, status, submitted_at);
